 &\preceq \Big[(t-s)^{\theta_1+[((\beta_1+\beta_2)/{\alpha_2})\wedge 1]-1}s^{\theta_2}\big(1+|\log (t-s)|\mathds 1_{\{\beta_1+\beta_2=\alpha_2\}}\big)\\
 &\quad+(t-s)^{\theta_1}
s^{\theta_2 +[((\beta_1+\beta_2)/{\alpha_2})\wedge 1]-1}\big(1+|\log s|\mathds 1_{\{\beta_1+\beta_2=\alpha_2\}}\big)\Big]\rho_{0}^{y,0}(t,x-y)\\
&\quad +(t-s)^{\theta_1+[({\beta_1}/{\alpha_2})\wedge 1]-1}s^{\theta_2}\big(1+|\log (t-s)|\mathds 1_{\{\beta_1=\alpha_2\}}\big)\rho_{0}^{y,\beta_2}(t,x-y)\\
&\quad+(t-s)^{\theta_1}s^{\theta_2+[({\beta_2}/{\alpha_2})\wedge 1] -1}\big(1+|\log s|\mathds 1_{\{\beta_2=\alpha_2\}}\big)\rho_0^{y,\beta_1}(t,x-y).
